import options from '../options';

/**
 * Diff the old and new properties of a VNode and apply changes to the DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to apply
 * changes to
 * @param {object} newProps The new props
 * @param {object} oldProps The old props
 * @param {boolean} isSvg Whether or not this node is an SVG node
 * @param {boolean} hydrate Whether or not we are in hydration mode
 */
export function diffProps(dom, newProps, oldProps, isSvg, hydrate) {
	let i;

	for (i in oldProps) {
		if (i !== 'children' && i !== 'key' && !(i in newProps)) {
			setProperty(dom, i, null, oldProps[i], isSvg);
		}
	}

display.text:
import { EMPTY_OBJ, IS_NON_DIMENSIONAL } from '../constants';
import options from '../options';

/**
 * Diff the old and new properties of a VNode and apply changes to the DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to apply
 * changes to
 * @param {object} newProps The new props
 * @param {object} oldProps The old props
 * @param {boolean} isSvg Whether or not this node is an SVG node
 * @param {boolean} hydrate Whether or not we are in hydration mode
 */
export function diffProps(dom, newProps, oldProps, isSvg, hydrate) {
	let i;

	for (i in oldProps) {
		if (i !== 'children' && i !== 'key' && !(i in newProps)) {
			setProperty(dom, i, null, oldProps[i], isSvg);
		}
	}

	for (i in newProps) {
		if (
			(!hydrate || typeof newProps[i] == 'function') &&
			i !== 'children' &&
			i !== 'key' &&
			i !== 'value' &&
			i !== 'checked' &&
			oldProps[i] !== newProps[i]
		) {
			setProperty(dom, i, newProps[i], oldProps[i], isSvg);
		}
	}
}

/**
 * Reconcile value/checked after children have been placed so host widgets
 * such as inputs, selects, progress bars and custom elements match the vnode.
 * @param {import('../internal').PreactElement} dom
 * @param {import('../internal').VNode} newVNode
 * @param {object} newProps
 * @param {object} oldProps
 */
export function diffFormProperties(dom, newVNode, newProps, oldProps) {
	let name;
	let nextValue;
	let prevProps;
	let prevValue;
	let prevChecked;
	let currentValue;
	let currentChecked;
	let hasDomProperty;
	let sourceProps;
	let applied;

	try {
		if (newVNode == null) {
			return;
		}
		if (newVNode.constructor !== undefined) {
			return;
		}

		prevProps = {};
		sourceProps = oldProps;
		if (sourceProps == null) {
			sourceProps = EMPTY_OBJ;
		}
		for (name in sourceProps) {
			if (name == 'key') {
				continue;
			}
			if (name == 'ref') {
				continue;
			}
			prevProps[name] = sourceProps[name];
		}
		prevValue = prevProps.value;
		prevChecked = prevProps.checked;
		currentValue = dom.value;
		currentChecked = dom.checked;

		if ('value' in newProps) {
			nextValue = newProps.value;
			if (nextValue !== undefined && nextValue !== currentValue) {
				hasDomProperty = 'value' in dom;
				applied = nextValue == null ? '' : nextValue;
				if (hasDomProperty) {
					dom.value = applied;
				} else {
					setProperty(dom, 'value', nextValue, prevValue, false);
				}
			}
		}

		if ('checked' in newProps) {
			nextValue = newProps.checked;
			if (nextValue !== undefined && nextValue !== currentChecked) {
				hasDomProperty = 'checked' in dom;
				applied = nextValue == null ? '' : nextValue;
				if (hasDomProperty) {
					dom.checked = applied;
				} else {
					setProperty(dom, 'checked', nextValue, prevChecked, false);
				}
			}
		}
	} catch (err) {
		options._catchError(err, newVNode);
	}
}

function setStyle(style, key, value) {
	if (key[0] === '-') {
		style.setProperty(key, value);
	} else if (value == null) {
		style[key] = '';
	} else if (typeof value != 'number' || IS_NON_DIMENSIONAL.test(key)) {
		style[key] = value;
	} else {
		style[key] = value + 'px';
	}
}

/**
 * Set a property value on a DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to modify
 * @param {string} name The name of the property to set
 * @param {*} value The value to set the property to
 * @param {*} oldValue The old value the property had
 * @param {boolean} isSvg Whether or not this DOM node is an SVG node or not
 */
export function setProperty(dom, name, value, oldValue, isSvg) {
	let useCapture, nameLower, proxy;

	if (isSvg && name == 'className') name = 'class';

	// if (isSvg) {
	// 	if (name === 'className') name = 'class';
	// } else if (name === 'class') name += 'Name';

	if (name === 'style') {
		if (typeof value == 'string') {
			dom.style.cssText = value;
		} else {
			if (typeof oldValue == 'string') {
				dom.style.cssText = oldValue = '';
			}

			if (oldValue) {
				for (name in oldValue) {
					if (!(value && name in value)) {
						setStyle(dom.style, name, '');
					}
				}
			}

			if (value) {
				for (name in value) {
					if (!oldValue || value[name] !== oldValue[name]) {
						setStyle(dom.style, name, value[name]);
					}
				}
			}
		}
	}
	// Benchmark for comparison: https://esbench.com/bench/574c954bdb965b9a00965ac6
	else if (name[0] === 'o' && name[1] === 'n') {
		useCapture = name !== (name = name.replace(/Capture$/, ''));
		nameLower = name.toLowerCase();
		if (nameLower in dom) name = nameLower;
		name = name.slice(2);

		if (!dom._listeners) dom._listeners = {};
		dom._listeners[name + useCapture] = value;

		proxy = useCapture ? eventProxyCapture : eventProxy;
		if (value) {
			if (!oldValue) dom.addEventListener(name, proxy, useCapture);
		} else {
			dom.removeEventListener(name, proxy, useCapture);
		}
	} else if (
		name !== 'list' &&
		name !== 'tagName' &&
		// HTMLButtonElement.form and HTMLInputElement.form are read-only but can be set using
		// setAttribute
		name !== 'form' &&
		name !== 'type' &&
		name !== 'size' &&
		name !== 'download' &&
		name !== 'href' &&
		!isSvg &&
		name in dom
	) {
		dom[name] = value == null ? '' : value;
	} else if (typeof value != 'function' && name !== 'dangerouslySetInnerHTML') {
		const oldName = name;
		if (name !== (name = name.replace(/^(xlink|xmlns):?/, ''))) {
			let ns =
				'http://www.w3.org/' +
				(/xm/.test(oldName) ? '2000/xmlns/' : '1999/xlink');
			if (/xm/.test(oldName)) {
				name = oldName === 'xmlns' ? oldName : 'xmlns:' + name;
			}
			if (value == null || value === false) {
				dom.removeAttributeNS(ns, name.toLowerCase());
			} else {
				dom.setAttributeNS(ns, name.toLowerCase(), value);
			}
		} else if (
			value == null ||
			(value === false &&
				// ARIA-attributes have a different notion of boolean values.
				// The value `false` is different from the attribute not
				// existing on the DOM, so we can't remove it. For non-boolean
				// ARIA-attributes we could treat false as a removal, but the
				// amount of exceptions would cost us too many bytes. On top of
				// that other VDOM frameworks also always stringify `false`.
				!/^ar/.test(name))
		) {
			dom.removeAttribute(name);
		} else {
			dom.setAttribute(name, value);
		}
	}
}

/**
 * Proxy an event to hooked event handlers
 * @param {Event} e The event object from the browser
 * @private
 */
function eventProxy(e) {
	this._listeners[e.type + false](options.event ? options.event(e) : e);
}

function eventProxyCapture(e) {
	this._listeners[e.type + true](options.event ? options.event(e) : e);
}

