const base = require('/testbed/karma.conf.js');

module.exports = function(config) {
	base(config);
	const launchers = config.customLaunchers || {};
	if (launchers.ChromeNoSandboxHeadless) {
		launchers.ChromeNoSandboxHeadless.flags.push('--disable-crash-reporter');
	}
	config.set({
		basePath: '/testbed',
		customLaunchers: launchers
	});
};

